import{_ as t,o as i,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Entités","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/fritzbox-to-mqtt/entities.md","filePath":"fr/projects/fritzbox-to-mqtt/entities.md","lastUpdated":1793127012000}'),l={name:"fr/projects/fritzbox-to-mqtt/entities.md"};function o(s,e,r,d,u,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<p><a id="entites"></a><a id="statut"></a></p><h1 id="entitaten" tabindex="-1">Entités <a class="header-anchor" href="#entitaten" aria-label="Permalink to &quot;Entités {#entitaten}&quot;">​</a></h1><p>Les entités sont créées via la découverte MQTT (MQTT Discovery).</p><h2 id="anrufbeantworter" tabindex="-1">Répondeur <a class="header-anchor" href="#anrufbeantworter" aria-label="Permalink to &quot;Répondeur {#anrufbeantworter}&quot;">​</a></h2><p>Pour chaque répondeur détecté, des entités (allant de <code>AB0</code> à <code>AB4</code>) sont créées :</p><ul><li>Nouveaux messages</li><li>Anciens messages</li><li>État</li><li>Interrupteur Marche/Arrêt</li></ul><p>Le nom du répondeur (tel qu&#39;il apparaît dans la FRITZ!Box) est conservé en tant qu&#39;attribut, mais n&#39;est pas utilisé dans les noms des entités.</p><h2 id="wlan" tabindex="-1">Wi-Fi <a class="header-anchor" href="#wlan" aria-label="Permalink to &quot;Wi-Fi {#wlan}&quot;">​</a></h2><p>Selon le modèle de FRITZ!Box, les éléments suivants sont créés :</p><ul><li>Wi-Fi 2,4 GHz Marche/Arrêt</li><li>Wi-Fi 2,4 GHz État</li><li>Wi-Fi 5 GHz Marche/Arrêt</li><li>Wi-Fi 5 GHz État</li><li>Wi-Fi Invité Marche/Arrêt</li><li>Wi-Fi Invité État</li></ul><p>Les capteurs d&#39;état Wi-Fi affichent <code>Ein</code> ou <code>Aus</code> ; l&#39;état brut fourni par la FRITZ!Box est conservé sous forme d&#39;attribut.</p><h2 id="wan-und-box-status" tabindex="-1">WAN et état de la FRITZ!Box <a class="header-anchor" href="#wan-und-box-status" aria-label="Permalink to &quot;WAN et état de la FRITZ!Box {#wan-und-box-status}&quot;">​</a></h2><ul><li>Connexion (téléchargement)</li><li>Connexion (envoi)</li><li>Débit de téléchargement</li><li>Débit d&#39;envoi</li><li>État de la liaison WAN</li><li>Rôle de la FRITZ!Box dans le réseau Mesh</li><li>Connexion PPP de la FRITZ!Box</li><li>Adresse IPv4 externe (PPP)</li><li>Adresse IPv6 externe</li><li>État DECT</li><li>DNS over TLS</li></ul><p><code>WAN Link Status</code> indique également <code>Ein</code> ou <code>Aus</code>.</p><p>Les valeurs facultatives non fournies par la FRITZ!Box sont masquées ou publiées sous la forme <code>unknown</code>.</p><h2 id="anruflisten-und-live-anrufmonitor" tabindex="-1">Listes d&#39;appels et moniteur d&#39;appels en direct <a class="header-anchor" href="#anruflisten-und-live-anrufmonitor" aria-label="Permalink to &quot;Listes d&#39;appels et moniteur d&#39;appels en direct {#anruflisten-und-live-anrufmonitor}&quot;">​</a></h2><p>Listes d&#39;appels configurables :</p><ul><li>tous les appels</li><li>appels entrants</li><li>appels sortants</li><li>appels manqués</li><li>appels rejetés</li><li>appels bloqués</li></ul><p>Le moniteur d&#39;appels en temps réel fournit des événements tels que <code>RING</code>, <code>CALL</code>, <code>CONNECT</code> et <code>DISCONNECT</code>.</p><h2 id="telefonbucher" tabindex="-1">Répertoires téléphoniques <a class="header-anchor" href="#telefonbucher" aria-label="Permalink to &quot;Répertoires téléphoniques {#telefonbucher}&quot;">​</a></h2><p>Les répertoires téléphoniques sont affichés avec les noms détectés de la FRITZ!Box. Les listes de blocage Tellows peuvent être masquées via des filtres de nom ou renommées de manière explicite via <code>phonebook_names</code>.</p><h2 id="dect" tabindex="-1">DECT <a class="header-anchor" href="#dect" aria-label="Permalink to &quot;DECT {#dect}&quot;">​</a></h2><p>Les informations suivantes sont publiées (en option) pour chaque combiné DECT détecté :</p><ul><li>numéro interne</li><li>identifiant de l&#39;appareil</li></ul><p><code>NoRingTime</code> n&#39;est volontairement plus publié.</p>',25)])])}const m=t(l,[["render",o]]);export{h as __pageData,m as default};
